/* Connected UI for the existing miniature preview. No external recognition/data calls. */
(() => {
'use strict';
const K=window.MiniKitchen,J=window.KitchenJournal,F=window.KitchenWorkflowModel,M=window.KitchenPlayModel,C=window.KitchenCatalog,A=window.UMFKitchenArt;
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const fmt=n=>n===null||n===undefined?'미입력':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:2});
const won=n=>n===null||n===undefined?'금액 미입력':fmt(n)+'원';
const find=id=>C.find(r=>r.id===id),world=()=>K.exportWorld(),flow=()=>J.getWorkflow(),play=()=>J.getSnapshot();
const EXTRA={calcium:['칼슘','mg'],sodium:['나트륨','mg'],sugar:['당류','g']};
const key=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+(++sequence)+'-'+Math.random().toString(36).slice(2));
let sequence=0,route='home',viewDay=today(),viewMonth=today().slice(0,7),activeItem=null,activeRecipe=null,search='',expiryFilter='',selectedIngredient='',filters={budget:'',time:'',exclude:''},pendingImport=null,photoDraft={product:null,expiry:null,fridge:null},attachment=null,lastStockUndo=null;
const zoneNames={freshLeft:'냉장 왼쪽',freshRight:'냉장 오른쪽',frozenLeft:'냉동 왼쪽',frozenRight:'냉동 오른쪽',doorFreshLeft:'냉장 왼쪽 문',doorFreshRight:'냉장 오른쪽 문',doorFrozenLeft:'냉동 왼쪽 문',doorFrozenRight:'냉동 오른쪽 문',seasoning:'양념 선반',counter:'조리대'};
const dateNo=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)/86400000;};
const delta=s=>s?dateNo(s)-dateNo(today()):null;
const liveStock=(date=today())=>world().items.filter(i=>['food','seasoning'].includes(i.kind)&&!i.depleted&&F.parseQuantity(i.quantity)?.baseAmount!==0&&(!i.expiry||i.expiry>=date));
const clean=s=>String(s).normalize('NFKC').replace(/\s+/g,'').toLowerCase();
const same=(name,ingredient)=>ingredient.split('/').some(n=>clean(name)===clean(n));
const ingredients=r=>[...new Set([...(r.f||[]),...(r.s||[]),...(r.p||[])])];
const art=i=>K.getArt(i);
const dish=r=>A.dishArt({id:r.name});
const field=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const numberField=(label,name,value='',attrs='')=>field(label,name,value,'number',`min="0" step="any" ${attrs}`);
const button=(label,action,arg='',primary=false)=>`<button type="button" class="small-action ${primary?'primary':''}" data-wf="${action}" data-arg="${esc(arg)}">${label}</button>`;
const hint=s=>`<p class="workflow-note">${s}</p>`;
const error=s=>{const e=$('#trayContent .workflow-feedback');if(e)e.textContent=s;else K.announce(s);};
function nav(section=route){
 const active=['recipe','recipes','recipeFacts','logMeal','plan','recipesReset'].includes(section)?'recipes':'hub';
 return `<nav class="workflow-nav" aria-label="부엌의 기능">${[['home','부엌'],['recipes','요리'],['hub','기록']].map(([id,label])=>`<button type="button" ${id==='home'?'data-wf="home"':`data-workflow="${id}"`} ${active===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;
}
function open(title,html,next){route=next;K.showTray(title,nav()+html+'<div class="workflow-feedback" role="status"></div>','한끼의 부엌');}
const footer=html=>`<div class="workflow-footer">${html}</div>`;
function balance(){
 const r=J.summary(today()),empty=r.rows.length===0;
 return `<div class="balance-head"><b>오늘의 균형</b><span>먹은 양 <span aria-hidden="true">/</span> 하루 목표</span></div><div class="balance-values">${['carb','protein','fat'].map(k=>{
  const n=r.nutrients[k],percent=n.percent===null?null:Math.round(n.percent);
  return `<div class="balance-value" data-balance="${k}"><span class="balance-name">${M.NUTRIENTS[k][0]}</span><div class="balance-number"><strong>${n.value===null?'—':fmt(n.value)}<small>g</small></strong><span>${n.target===null?'(미설정)':'('+fmt(n.target)+'g)'}</span></div><div class="balance-meter"><div class="balance-track" ${percent!==null?`role="progressbar" aria-label="${M.NUTRIENTS[k][0]} 목표 대비" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,percent)}"`:''}><i style="width:${percent===null?0:Math.min(100,percent)}%"></i></div><small class="balance-percent">${percent===null?(n.target===null?'—':'기록 대기'):fmt(percent)+'%'}</small></div>${n.missing?`<small class="balance-status">${n.missing}끼 미입력</small>`:''}</div>`;
 }).join('')}</div>${empty?'<span class="balance-empty">오늘 먹은 한 끼부터 남겨 보세요 <b>식사 기록하기 ›</b></span>':'<span class="balance-note">직접 기록한 식사 기준 · 눌러서 자세히 보기</span>'}`;
}
function update(){
 const daily=$('#dailyBalance');if(daily)daily.innerHTML=balance();
 const counts={overdue:0,today:0,tomorrow:0,soon:0};for(const i of world().items){if(!['food','seasoning'].includes(i.kind)||i.depleted||F.parseQuantity(i.quantity)?.baseAmount===0||!i.expiry)continue;const d=delta(i.expiry);if(d<=3)counts[d<0?'overdue':d===0?'today':d===1?'tomorrow':'soon']++;}
 const expiry=$('#expirySummary');if(expiry)expiry.innerHTML=Object.entries(counts).filter(([,v])=>v).map(([k,v])=>`<button type="button" data-wf="expiryFilter" data-arg="${k}" class="expiry-chip ${k==='overdue'?'overdue':''}"><span>${{overdue:'기한 경과',today:'오늘까지',tomorrow:'내일',soon:'2~3일'}[k]}</span><b>${v}</b></button>`).join('')||'<span class="expiry-empty">기한을 입력하면 먼저 먹을 재료를 알려드려요</span>';
 const snap=K.getSnapshot(),item=snap.items.find(i=>i.id===snap.selected&&['food','seasoning'].includes(i.kind));
 const progress=$('#kitchenProgress>span');if(progress)progress.textContent=item?item.name:'우리 집 재료';
 const selectedMeta=$('#selectedItemMeta');if(selectedMeta)selectedMeta.textContent=item?(item.quantity||'수량 미입력')+' · '+(item.expiry?'표시 기한 '+item.expiry:'기한 미입력'):'재료를 눌러 수량과 기한을 확인해요';
 const journal=$('#openJournal');if(journal)journal.textContent=item?'이 재료로 요리 찾기':'재료 목록 보기';
 const settings=flow().theme;document.body.classList.toggle('theme-stone',settings.background==='stone');document.body.classList.toggle('label-minimal',settings.labels==='minimal');document.body.classList.toggle('organizer-outline',settings.organizer);
 const report=J.summary(today()),state=play(),milestone=$('#kitchenMilestone');
 if(milestone){
  const goal=report.goal,percent=Math.round(goal.value/goal.target*100),ready=Object.entries(M.REWARDS).find(([id,reward])=>!state.owned.includes(id)&&report.tickets>=reward.cost),owned=state.owned.map(id=>M.REWARDS[id].name);
  milestone.innerHTML=`<div class="milestone-top"><span>나의 부엌</span><strong>요리 도감 ${report.cooked.length}<small> / ${C.length}</small></strong></div><div class="milestone-main"><div><b>${esc(goal.label)}</b><small>${goal.value===goal.target?'선택한 목표를 달성했어요':'현재 '+goal.value+' / '+goal.target+' · 나의 속도로 채워요'}</small></div><span>${percent}%</span></div><div class="milestone-track" data-milestone-progress role="progressbar" aria-label="${esc(goal.label)}" aria-valuemin="0" aria-valuemax="${goal.target}" aria-valuenow="${goal.value}"><i style="width:${percent}%"></i></div><div class="milestone-footer"><span>${ready?'받을 수 있는 소품 · '+esc(ready[1].name):'꾸밈권 '+report.tickets+'개 · 새 요리 첫 기록마다 1개'}</span>${button(ready?'소품 고르기':'도감 보기',ready?'rewards':'book')}</div>${owned.length?`<div class="milestone-owned"><span>내가 모은 소품</span><strong>${owned.map(esc).join(' · ')}</strong></div>`:''}`;
 }
 const panel=$('#desktopSummary');if(panel){
  const near=liveStock().filter(i=>i.expiry&&delta(i.expiry)<=3),rows=[...C].sort((a,b)=>near.filter(i=>ingredients(b).some(n=>same(i.name,n))).length-near.filter(i=>ingredients(a).some(n=>same(i.name,n))).length);
  panel.innerHTML=`<h2>${near.length?'먼저 먹을 재료로':'우리 집 요리'}</h2><p class="sidebar-intro">가진 재료를 살펴보고 한 끼를 골라요</p>${rows.slice(0,3).map(r=>{const x=matches(r);return `<button type="button" class="workflow-card sidebar-recipe" data-wf="recipe" data-arg="${r.id}"><span class="sidebar-recipe-art">${dish(r)}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.time)} · 재료 ${x.registered.length}/${x.required.length}종 기록</small></span></button>`;}).join('')}<div class="workflow-footer">${button('이번 주 식단','plan')}${button('전체 요리','recipes')}</div>`;
 }
}
function hub(){
 const report=J.summary(today()),monthlyReport=F.monthly(flow(),play(),today().slice(0,7));
 const groups=[['오늘의 식탁',[['nutrition','오늘의 영양','식사와 하루 목표'],['plan','이번 주 식단','한 끼씩 미리 계획'],['supplements','영양제','내 일정과 복용 기록']]],['생활 기록',[['shopping','장보기','부족한 재료 모으기'],['budget','식비·예산','실제 지출과 남은 예산'],['monthly','한 달의 식탁','식사·비용·영양 기록']]],['나의 부엌',[['book','요리 도감','만들어 본 요리와 내 팁'],['decor','부엌 꾸미기','정리함·라벨·소품'],['inventory','재료 목록','이름·수량·기한 관리'],['settings','목표와 설정','하루 목표·선호·기록 보관']]]];
 open('나의 기록',`<div class="record-overview"><div><span>오늘 기록한 식사</span><strong>${report.rows.length}<small> 끼</small></strong></div><div><span>이달 입력한 식비</span><strong>${won(monthlyReport.spending)}</strong></div></div>${groups.map(([title,items])=>`<section class="record-group"><h3>${title}</h3><div class="workflow-grid">${items.map(([id,name,note])=>`<button type="button" class="workflow-card" data-workflow="${id}"><strong>${name}</strong><small>${note}</small><span class="row-chevron" aria-hidden="true">›</span></button>`).join('')}</div></section>`).join('')}`,'hub');
}
function inventory(){
 const filterNames={overdue:'기한 경과',today:'오늘까지',tomorrow:'내일',soon:'2~3일 이내'};
 const rows=world().items.filter(i=>{
  if(!['food','seasoning'].includes(i.kind)||search&&!clean(i.name).includes(clean(search)))return false;
  if(!expiryFilter)return true;
  if(i.depleted||F.parseQuantity(i.quantity)?.baseAmount===0||!i.expiry)return false;
  const d=delta(i.expiry);return expiryFilter==='overdue'?d<0:expiryFilter==='today'?d===0:expiryFilter==='tomorrow'?d===1:d>=2&&d<=3;
 });
 open('우리 집 재료',`<div class="inventory-toolbar"><form data-wf-form="search" class="inventory-search"><label class="workflow-label">재료·양념 찾기<input name="search" value="${esc(search)}" placeholder="이름으로 검색"></label><button class="small-action" type="submit">검색</button></form><div class="workflow-footer">${button('재료 추가','add','',true)}${button('전체 기한순','expirySort')}</div></div>${expiryFilter?`<div class="current-filter"><span>${filterNames[expiryFilter]} · ${rows.length}개 묶음</span>${button('전체 보기','inventoryReset')}</div>`:`<p class="inventory-count">${rows.length}개 묶음 · 기한이 가까운 순서</p>`}<div class="inventory-list">${rows.length?rows.sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999')).map(i=>{const d=delta(i.expiry),tone=i.depleted?'depleted':d===null?'unknown':d<0?'overdue':d<=1?'urgent':'normal',expiryText=i.depleted?'소진':d===null?'기한 미입력':d<0?'기한 경과':d===0?'오늘까지':d===1?'내일까지':d+'일 남음';return `<button type="button" class="workflow-row inventory-row" data-wf="item" data-arg="${i.id}" data-tone="${tone}"><span class="inventory-art">${art(i)}</span><span class="inventory-copy"><strong>${esc(i.name)}</strong><span class="inventory-quantity">${esc(i.quantity||'수량 미입력')}</span><small>${zoneNames[i.zone]}</small></span><span class="inventory-expiry"><b>${expiryText}</b><small>${esc(i.expiry)}</small></span><span class="row-chevron" aria-hidden="true">›</span></button>`;}).join(''):'<p class="workflow-empty">조건에 맞는 재료가 없어요.</p>'}</div>`,'inventory');
}
function item(id){
 activeItem=id;attachment=null;const i=world().items.find(x=>x.id===id);if(!i)return;
 const d=delta(i.expiry),expiryText=d===null?'기한을 확인해 주세요':d<0?'표시 기한이 지났어요':d===0?'오늘까지 먼저 먹어요':d===1?'내일까지 먼저 먹어요':d+'일 남았어요';
 open(i.name,`<form id="ingredientForm" data-wf-form="item" data-id="${i.id}"><div class="ingredient-identity ingredient-summary"><div class="ingredient-preview">${art(i)}</div><div class="ingredient-summary-copy"><span>${zoneNames[i.zone]}</span><strong>${esc(i.quantity||'수량 미입력')}</strong><small class="${d!==null&&d<=1?'is-urgent':''}">${expiryText}</small>${i.expiry?`<time datetime="${esc(i.expiry)}">${esc(i.expiry)}</time>`:''}</div></div><div class="ingredient-primary-actions">${button('이 재료로 요리 찾기','ingredientRecipes',i.name,true)}</div><section class="ingredient-edit-section"><h3>수량과 보관</h3><div class="workflow-fields">${field('수량과 단위','quantity',i.quantity,'text','maxlength="80" placeholder="예: 6개, 300g"')}<label>보관 위치<select name="zone">${Object.entries(zoneNames).map(([k,v])=>`<option value="${k}" ${i.zone===k?'selected':''}>${v}</option>`).join('')}</select></label></div></section><section class="ingredient-edit-section"><h3>기한 관리</h3><div class="workflow-fields">${field('표시된 기한','expiry',i.expiry,'date','min="1900-01-01" max="9999-12-31"')}<label>기한 종류<select name="expiryType">${[['printed','표시 기한'],['useBy','소비기한'],['bestBefore','유통기한'],['unknown','확인 필요']].map(([k,v])=>`<option value="${k}" ${i.expiryType===k?'selected':''}>${v}</option>`).join('')}</select></label>${field('개봉일 (선택)','opened',i.opened||'','date')}</div></section><details class="ingredient-photos"><summary>이름·사진 수정</summary>${field('재료 이름','name',i.name,'text','required maxlength="120"')}<label class="file-label">제품 사진 수정<input type="file" name="itemPhoto" accept="image/*" data-photo="item"></label><div id="itemPhotoPreview"></div>${i.photo?`<img class="workflow-photo" src="${i.photo}" alt="등록한 제품 사진">`:''}${i.expiryPhoto?`<img class="workflow-photo" src="${i.expiryPhoto}" alt="등록한 기한 사진">`:''}<p class="workflow-hint">선택한 사진은 이 기기에 축소해 보관해요.</p></details><details class="ingredient-more"><summary>배치·소진 관리</summary><div class="ingredient-tools" aria-label="재료 정리">${button('앞으로','layerFront',id)}${button('뒤로','layerBack',id)}${button('사용·소진','deplete',id)}${button('폐기 기록','waste',id)}${button('실행 취소','stockUndo')}</div>${hint('개·모·팩의 무게는 추정하지 않아요. 같은 종류의 g·kg, mL·L만 변환해요.')}</details><div class="form-actions"><button type="button" class="small-action" data-close>닫기</button><button type="submit" class="small-action primary">저장</button></div></form>`,'item');
}
function add(){photoDraft={product:null,expiry:null,fridge:null};open('재료를 추가해요',`<div class="workflow-grid">${[['photos','제품 사진 2장','제품과 기한을 각각 확인'],['fridgePhoto','냉장고 전체 사진','사진을 보며 여러 재료 입력'],['manualAdd','직접 입력','이름·수량·기한부터'],['seasoningAdd','양념 추가','양념도 기한·개봉일 관리']].map(([id,name,note])=>`<button type="button" class="workflow-card" data-wf="${id}"><strong>${name}</strong><small>${note}</small></button>`).join('')}</div>${hint('자동 사진 인식은 아직 연결 전이에요. 현재는 사진을 보며 직접 확인한 재료를 등록할 수 있어요.')}`,'add');}
function photoPage(whole=false){const slots=whole?[['fridge','냉장고 전체 사진']]:[['product','제품 사진'],['expiry','기한 사진']];open(whole?'냉장고 사진으로 재료 확인':'제품과 기한 사진 2장',`<div class="workflow-grid">${slots.map(([k,n])=>`<label class="photo-slot">${n}<input type="file" accept="image/*" data-photo="${k}">${photoDraft[k]?`<img class="workflow-photo" src="${photoDraft[k]}" alt="선택한 ${n}">`:'<p class="workflow-empty">사진을 선택해 주세요</p>'}</label>`).join('')}</div>${hint('자동 인식 연결 전 · 사진의 이름과 표시 기한을 직접 확인해 주세요. 가려진 재료나 읽기 어려운 날짜를 임의로 채우지 않아요.')}<button class="small-action" type="button" disabled>자동으로 읽기 · 연결 전</button>${footer(button(whole?'사진 보며 후보 입력':'확인하고 직접 입력',whole?'wholeCandidates':'manualAdd','',true)+button('사진 없이 입력','manualNoPhoto'))}` ,whole?'fridgePhoto':'photos');}
function manualAdd(seasoning=false){attachment=photoDraft.product;open(seasoning?'양념을 추가해요':'재료 내용을 확인해요',`${photoDraft.product||photoDraft.expiry?`<div class="workflow-grid">${photoDraft.product?`<img class="workflow-photo" src="${photoDraft.product}" alt="제품 사진">`:''}${photoDraft.expiry?`<img class="workflow-photo" src="${photoDraft.expiry}" alt="표시 기한 원문">`:''}</div>`:''}<form data-wf-form="add" id="addIngredientForm"><div class="workflow-fields">${field('이름','name','','text','required maxlength="120" placeholder="예: 계란"')}${field('수량과 단위','quantity','','text','maxlength="80" placeholder="예: 6개, 150ml"')}${field('표시 기한','expiry','','date')}${field('개봉일 (선택)','opened','','date')}<label>재료 종류<select name="kind"><option value="food" ${!seasoning?'selected':''}>식재료</option><option value="seasoning" ${seasoning?'selected':''}>양념</option></select></label><label>보관 위치<select name="zone">${Object.entries(zoneNames).map(([k,n])=>`<option value="${k}" ${k===(seasoning?'doorFreshRight':'freshLeft')?'selected':''}>${n}</option>`).join('')}</select></label><label class="wide">아이콘<select name="picture"><option value="miniature">기본 미니어처 그림</option>${photoDraft.product?'<option value="photo">내 제품 사진</option>':''}</select></label></div><div id="duplicateHint"></div>${hint('표시 기한을 확인한 뒤 저장해 주세요. 같은 재료도 다른 기한이면 별도 묶음으로 보관해요. 새 그림 자동 생성은 연결 전이며 이름에 맞는 기존 미니어처를 사용할 수 있어요.')}<div class="workflow-footer"><button type="submit" class="small-action primary">확인한 재료 추가</button>${button('돌아가기','add')}</div></form>`,'manualAdd');}
function wholeCandidates(){open('사진을 보며 재료를 확인해요',`${photoDraft.fridge?`<img class="workflow-photo" src="${photoDraft.fridge}" alt="내 냉장고 사진">`:''}${hint('자동 인식 연결 전이에요. 보이는 재료를 직접 입력하고 확인한 항목만 추가해 주세요. 기존 재고를 덮어쓰지 않아요.')}<form data-wf-form="candidates" id="candidateForm"><div id="candidateRows">${candidateRow(0)}</div>${footer(button('후보 하나 더','candidateAdd')+'<button type="submit" class="small-action primary">확인한 항목 저장</button>')}</form>`,'wholeCandidates');}
function candidateRow(n){return `<fieldset class="workflow-card" data-candidate><legend>재료 ${n+1}</legend><label class="check-row"><input type="checkbox" name="include${n}" checked>이 재료 추가</label><div class="workflow-fields">${field('이름','name'+n,'','text','maxlength="120"')}${field('수량·단위','quantity'+n,'','text','maxlength="80"')}${field('기한 (모르면 빈칸)','expiry'+n,'','date')}<label>보관 위치<select name="zone${n}">${Object.entries(zoneNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div></fieldset>`;}
function matches(r){const stock=liveStock(),required=ingredients(r),registered=required.filter(n=>stock.some(i=>same(i.name,n))),missing=required.filter(n=>!registered.includes(n));return {registered,missing,required};}
function recipes(){
 const s=flow();let rows=C.filter(r=>(!selectedIngredient||ingredients(r).some(n=>same(selectedIngredient,n)))&&(!filters.time||parseInt(r.time,10)<=Number(filters.time))&&(!filters.budget||s.recipeFacts[r.id]?.cost!==null&&s.recipeFacts[r.id]?.cost!==undefined&&s.recipeFacts[r.id].cost<=Number(filters.budget))&&!String(filters.exclude||s.exclusions).split(/[,\n]/).map(x=>x.trim()).filter(Boolean).some(n=>ingredients(r).some(v=>same(n,v))));
 const near=liveStock().filter(i=>i.expiry&&delta(i.expiry)<=3);rows.sort((a,b)=>near.filter(i=>ingredients(b).some(n=>same(i.name,n))).length-near.filter(i=>ingredients(a).some(n=>same(i.name,n))).length);
 const conditions=[selectedIngredient,filters.time?filters.time+'분 이내':'',filters.budget?won(Number(filters.budget))+' 이내':'',filters.exclude||s.exclusions?'피할 재료 반영':''].filter(Boolean);
 open(selectedIngredient?selectedIngredient+' 활용 요리':'오늘의 요리',`<div class="recipe-results-heading"><div><p>먼저 먹을 재료부터 한 끼를 골라요</p><strong>${rows.length}가지 요리</strong></div>${button('이번 주 식단','plan')}</div><details class="recipe-filters"><summary><strong>조건 조정</strong><span>${esc(conditions.join(' · ')||'재료 · 시간 · 예산')}</span></summary><form data-wf-form="recipeFilters"><div class="workflow-fields"><label>먼저 사용할 재료<select name="ingredient"><option value="">전체 재료</option>${[...new Set(world().items.filter(i=>['food','seasoning'].includes(i.kind)).map(i=>i.name))].map(n=>`<option value="${esc(n)}" ${n===selectedIngredient?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${numberField('조리 시간 (분)','time',filters.time,'step="1" placeholder="제한 없음"')}${numberField('입력 원가 기준 예산 (원)','budget',filters.budget,'step="1" placeholder="제한 없음"')}${field('피할 재료 (쉼표 구분)','exclude',filters.exclude||s.exclusions)}</div><div class="workflow-footer"><button type="submit" class="small-action primary">조건 적용</button>${button('전체 보기','recipesReset')}</div>${hint('기한이 지난 재고는 보유에서 제외해요. 예산을 적용하면 원가 미입력 요리는 제외해요.')}</form></details><div class="recipe-results">${rows.map(r=>{const x=matches(r),fact=s.recipeFacts[r.id];return `<button type="button" class="workflow-card recipe-result" data-wf="recipe" data-arg="${r.id}"><span class="recipe-result-art">${dish(r)}</span><span class="recipe-result-copy"><strong>${esc(r.name)}</strong><span class="recipe-result-meta">${esc(r.time)} · ${won(fact?.cost)}</span><span class="recipe-stock-fact">재료 ${x.registered.length}<small> / ${x.required.length}종 기록</small></span><small class="recipe-missing">${x.missing.length?'미등록 '+esc(x.missing.slice(0,3).join(' · ')):'재료 이름이 모두 기록돼 있어요'}</small></span><span class="row-chevron" aria-hidden="true">›</span></button>`;}).join('')}</div>${rows.length?'<p class="recipe-result-note">이름의 일치는 수량 충분함을 뜻하지 않아요. 요리에서 실제 사용량을 확인해 주세요.</p>':'<p class="workflow-empty">조건에 맞는 요리가 없어요. 조건을 조정해 보세요.</p>'}`,'recipes');
}
function recipe(id){const r=find(id);if(!r)return;activeRecipe=id;J.discover(id);const s=flow(),facts=s.recipeFacts[id],notes=s.recipeNotes[id]||{note:'',variation:''},x=matches(r);open(r.name,`<div class="recipe-hero">${dish(r)}</div><div class="recipe-facts"><span>${esc(r.time)}</span><span>${esc(r.level)}</span><span>기준 레시피 1회분</span></div>${facts?`<div class="workflow-note">입력한 1회분 영양 · 열량 ${facts.kcal===null?'미입력':fmt(facts.kcal)+'kcal'}<br>탄수화물 ${facts.carb===null?'미입력':fmt(facts.carb)+'g'} · 단백질 ${facts.protein===null?'미입력':fmt(facts.protein)+'g'} · 지방 ${facts.fat===null?'미입력':fmt(facts.fat)+'g'}<br>사용 재료비 ${won(facts.cost)}<br>출처 메모: ${esc(facts.source||'미입력')}</div>`:hint('레시피 영양·원가는 미입력이에요. 확인한 자료가 있으면 직접 기록할 수 있어요.')}<div class="workflow-footer">${button('영양·원가 입력','recipeFacts',id)}${button('먹은 분량 기록','logMeal',id,true)}${button('식단에 담기','planRecipe',id)}</div><h3>필요한 재료</h3><dl class="recipe-amounts">${Object.entries(r.amounts).map(([n,a])=>`<div><dt>${esc(n)} <small>${esc(a)}</small></dt><dd>${liveStock().filter(i=>same(i.name,n)).map(i=>esc(i.quantity||'수량 미입력')).join(' · ')||'보유 기록 없음'}</dd></div>`).join('')}</dl>${x.missing.length?footer(button('부족 재료를 장보기로','missingToShopping',id)):hint('재료 이름이 기록돼 있어요. 실제 수량과 단위는 따로 확인해 주세요.')}<h3>만드는 순서</h3><ol class="recipe-steps">${r.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><form data-wf-form="recipeNotes" data-id="${id}" class="notes-box"><h3>나만의 요리 기록</h3><label class="workflow-label">나의 팁<textarea name="note" rows="3" maxlength="3000">${esc(notes.note)}</textarea></label><label class="workflow-label">대체 재료·내 버전<textarea name="variation" rows="2" maxlength="1000">${esc(notes.variation)}</textarea></label><button type="submit" class="small-action">내 팁 저장</button></form>${footer(button('조리대에 놓기','counterRecipe',id))}`,'recipe');}
function factsForm(id){const r=find(id),f=flow().recipeFacts[id]||{};open('레시피 영양·원가 입력',`${hint(esc(r.name)+' · 기준 레시피 1회분의 값을 입력해 주세요. 모르는 값은 비워 두고 출처·기준량을 메모해 주세요.')}<form data-wf-form="facts" data-id="${id}"><div class="workflow-fields">${Object.entries(M.NUTRIENTS).map(([k,[n,u]])=>numberField(n+' ('+u+')',k,f[k]??'')).join('')}${Object.entries(EXTRA).map(([k,[n,u]])=>numberField(n+' ('+u+', 선택)',k,f[k]??'')).join('')}${numberField('사용 재료비 (원)','cost',f.cost??'','step="1"')}${field('출처·기준량 메모','source',f.source||'','text','maxlength="300"')}</div><div class="workflow-footer"><button class="small-action primary" type="submit">입력값 저장</button></div></form>`,'recipeFacts');}
function logMeal(id=null,editId=null){const original=editId?play().meals.find(m=>m.id===editId):null;if(original)viewDay=original.day;const r=find(id),f=original?original.nutrients:r&&flow().recipeFacts[id];let stock=liveStock(viewDay);if(original){const w=world(),tx=flow().transactions.find(t=>t.mealId===original.id&&t.active);if(tx)F.reverseDeductions(w,tx.deductions);stock=w.items.filter(i=>['food','seasoning'].includes(i.kind)&&!i.depleted&&(!i.expiry||i.expiry>=viewDay));}const uses=r?Object.entries(r.amounts).map(([name,amount])=>{const have=stock.find(i=>same(i.name,name)),p=have&&F.parseQuantity(have.quantity),n=F.parseQuantity(amount);const prior=original&&flow().transactions.find(t=>t.mealId===original.id&&t.active)?.deductions.find(d=>d.itemId===have?.id);if(prior&&p)amount=F.quantity(prior.amount,p);const needed=F.parseQuantity(amount);return {name,amount,item:have,compatible:!!p&&!!needed&&p.baseUnit===needed.baseUnit&&p.baseAmount>=needed.baseAmount};}):[];open('먹은 분량을 기록해요',`<form id="workflowMealForm" data-wf-form="meal" data-id="${id||''}" data-edit="${editId||''}"><div class="workflow-fields">${field('식사 이름','name',original?.name||r?.name||'','text','required maxlength="120"')}${field('날짜','day',viewDay,'date','required')}${numberField('기준 레시피를 먹은 비율','portions',1,'min="0.01" max="100"')}${field('먹은 분량 메모','portion',original?.portion||'','text','maxlength="80" placeholder="예: 1인분, 반 공기"')}</div>${r?`<div class="recipe-hero">${dish(r)}</div>`:''}<h3>먹은 분량 전체의 영양값</h3>${hint('아래 값은 실제 먹은 분량 전체의 값이에요. 입력한 레시피 정보가 있으면 가져오며, 비율을 바꾼 뒤에는 값도 확인해 주세요. 미입력은 0으로 채우지 않아요.')}<div class="workflow-fields">${Object.entries(M.NUTRIENTS).map(([k,[n,u]])=>numberField(n+' ('+u+')',k,f?.[k]??'')).join('')}</div><details class="journal-section"><summary>칼슘·나트륨·당류 (선택)</summary><div class="workflow-fields">${Object.entries(EXTRA).map(([k,[n,u]])=>numberField(n+' ('+u+')',k,original?(flow().extraNutrients?.[original.id]?.[k]??''):(flow().recipeFacts[id]?.[k]??''))).join('')}</div></details><h3>확인한 재료만 재고에서 차감</h3>${uses.length?uses.map((u,i)=>`<div class="usage-row"><input type="checkbox" name="use${i}" ${u.compatible?'checked':''} ${!u.item?'disabled':''} aria-label="${esc(u.name)} 재고 차감"><div><strong>${esc(u.name)}</strong><small>${u.item?'보유 '+esc(u.item.quantity||'수량 미입력'):'보유 기록 없음'} · 기준 ${esc(u.amount)}</small><input type="hidden" name="item${i}" value="${u.item?.id||''}"></div><input type="text" name="qty${i}" value="${esc(u.compatible?u.amount:'')}" placeholder="사용량" maxlength="80" aria-label="${esc(u.name)} 실제 사용량"></div>`).join(''):hint('직접 입력한 식사는 재고를 자동 차감하지 않아요. 재료에서 수량을 직접 수정할 수 있어요.')}<p class="workflow-hint">기록을 확정할 때만 선택한 사용량과 영양을 반영해요. 단위가 다르면 사용량을 직접 확인해 주세요.</p><div class="workflow-footer"><button class="small-action primary" type="submit">먹었어요 · 기록</button></div></form>`,'logMeal');}
function cancelMeal(id){const record=play().meals.find(r=>r.id===id);if(!record)return;const txn=flow().transactions.find(r=>r.mealId===id&&r.active);open('이 식사 기록을 취소할까요?',`<h3>${esc(record.name)}</h3><p class="tray-note">${esc(record.day)} · ${esc(record.portion||'분량 메모 없음')}</p>${txn?.deductions.length?`<table class="workflow-table"><thead><tr><th>복구할 재료</th><th>수량</th></tr></thead><tbody>${txn.deductions.map(d=>{const i=world().items.find(x=>x.id===d.itemId);return `<tr><td>${esc(i?.name||'삭제된 재료')}</td><td>+${fmt(d.amount)}${esc(d.baseUnit)}</td></tr>`;}).join('')}</tbody></table>`:hint('이 기록에 연결된 재고 차감은 없어요.')} ${hint('취소하면 이 식사에 기록한 영양값을 빼고, 연결된 재고 차감이 있으면 함께 복구해요. 이후 수량을 직접 바꾼 재료는 확인이 필요해요.')}<div class="workflow-footer">${button('돌아가기','nutrition')}${button('기록 취소','confirmCancelMeal',id,true)}</div>`,'cancelMeal');}
function undoMeal(){J.transact(({world:w,play:p,flow:s})=>{const last=s.lastCanceled;if(!last)throw new Error('복구할 취소 기록이 없어요.');const t=s.transactions.find(x=>x.mealId===last.record.id);if(t){F.reverseDeductions(w,t.deductions,-1);t.active=true;}p.restoreMeal(last.record);s.lastCanceled=null;});nutrition();error('취소했던 식사와 연결 재고·영양을 복구했어요.');}
function nutrition(){route='nutrition';J.show('nutrition');}
function enhanceJournal(tab){
 route=tab;$('#trayContent .journal-tabs')?.remove();
 $('#trayContent').insertAdjacentHTML('afterbegin',nav(tab));
 if(tab==='book'){$('#trayContent').insertAdjacentHTML('beforeend',footer(button('부엌 꾸미기','decor')+button('목표·보상','rewards')));return;}
 if(tab==='rewards'){$('#trayContent').insertAdjacentHTML('beforeend',footer(button('요리 도감','book')+button('부엌 꾸미기','decor')));return;}
 if(tab!=='nutrition')return;
 $('#trayContent').insertAdjacentHTML('beforeend',footer(button('하루 목표 설정','targets')+button('월간 기록','monthly')));
 const day=$('#journalDay')?.value||today();viewDay=day;const rows=play().meals.filter(m=>m.day===day),s=flow();
 $('#trayContent').insertAdjacentHTML('beforeend',`<h3>추가 성분 정보</h3><div class="workflow-grid">${Object.entries(EXTRA).map(([k,[n,u]])=>{const known=rows.map(m=>s.extraNutrients?.[m.id]?.[k]).filter(v=>typeof v==='number'),target=s.extraTargets?.[k];return `<section class="workflow-card"><strong>${n}</strong><span>${known.length?fmt(known.reduce((a,b)=>a+b,0))+u:'미입력'} ${target?'(목표 '+fmt(target)+u+')':''}</span><small>${rows.length-known.length}끼 미입력</small></section>`;}).join('')}</div>`+hint('직접 정한 목표와 입력한 값만 합산해요. 식품별 성분과 실제 먹은 양을 확인해 주세요. 개인별 공식 권장량·식품 성분 데이터는 아직 연결 전이에요.')+`<p class="tray-note"><a href="https://various.foodsafetykorea.go.kr/nutrient/" target="_blank" rel="noopener noreferrer">식품영양성분 자료 확인 ↗</a></p>`);
}
function plan(recipeId=null){const start=new Date(viewDay+'T12:00:00');start.setDate(start.getDate()-((start.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');});const s=flow(),rows=s.plans.filter(p=>p.day===viewDay);open('이번 주 식단',`<label class="workflow-label">살펴볼 날짜<input type="date" id="planDay" value="${viewDay}"></label><div class="workflow-week">${days.map((d,i)=>`<button class="workflow-day" type="button" data-wf="planDay" data-arg="${d}"><small>${['월','화','수','목','금','토','일'][i]}</small><strong>${Number(d.slice(8))}</strong><small>${s.plans.filter(p=>p.day===d).length}끼 계획</small></button>`).join('')}</div>${hint('식단은 계획이에요. 먹은 식사를 따로 기록하기 전까지 영양·재고·실제 지출에 반영되지 않아요.')}<h3>${esc(viewDay)} 식단</h3>${rows.map(p=>{const r=find(p.recipeId);return `<div class="workflow-row">${dish(r)}<div><strong>${{breakfast:'아침',lunch:'점심',dinner:'저녁'}[p.slot]} · ${esc(r.name)}</strong><small>기준 레시피 ${fmt(p.portions)}회분 · 원가 ${won(s.recipeFacts[r.id]?.cost===null||!s.recipeFacts[r.id]?null:s.recipeFacts[r.id].cost*p.portions)}</small></div>${button('기록','logMeal',r.id)}${button('빼기','removePlan',p.id)}</div>`;}).join('')||'<p class="workflow-empty">이날의 식단이 아직 없어요.</p>'}<form data-wf-form="plan"><h3>식단에 담기</h3><div class="workflow-fields">${field('날짜','day',viewDay,'date','required')}<label>끼니<select name="slot"><option value="breakfast">아침</option><option value="lunch" selected>점심</option><option value="dinner">저녁</option></select></label><label>요리<select name="recipeId">${C.map(r=>`<option value="${r.id}" ${r.id===recipeId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label>${numberField('기준 레시피 비율','portions',1,'min="0.01" max="100"')}</div><button class="small-action primary" type="submit">식단 계획 저장</button></form>${footer(button('이날의 부족 재료를 장보기로','planShopping',viewDay)+button('식비 예산','budget'))}`,'plan');}
function shopping(){const s=flow();open('장보기',`${hint('부족 재료와 직접 추가한 목록이에요. 예상비는 구매 전 참고용이며 실제 지출에 포함되지 않아요.')} ${s.shopping.length?s.shopping.map(r=>`<div class="workflow-row"><input type="checkbox" data-shopping-check="${r.id}" ${r.checked?'checked':''} aria-label="${esc(r.name)} 선택">${A.foodArt(A.foodIdForName(r.name))}<div><strong>${esc(r.name)} ${esc(r.quantity)}</strong><small>예상 ${won(r.estimate)}</small></div>${button('구매','purchase',r.id)}${button('빼기','removeShopping',r.id)}</div>`).join(''):'<p class="workflow-empty">필요한 재료를 모아 보세요.</p>'}<form data-wf-form="shopping"><h3>직접 추가</h3><div class="workflow-fields">${field('재료','name','','text','required maxlength="120"')}${field('수량·단위','quantity','','text','maxlength="80"')}${numberField('예상 금액 (원, 선택)','estimate','','step="1"')}</div><button class="small-action" type="submit">목록에 추가</button></form><div class="workflow-total"><span>입력한 예상비 합계</span><b>${won(s.shopping.reduce((n,r)=>n+(r.estimate??0),0))}</b></div>${s.shopping.some(r=>r.estimate===null)?'<p class="workflow-hint">금액 미입력 항목은 합계에 포함되지 않았어요.</p>':''}${footer(button('실제 지출과 예산','budget')+button('요리에서 재료 찾기','recipes'))}`,'shopping');}
function purchase(id){const row=flow().shopping.find(r=>r.id===id);if(!row)return;open('구매한 내용을 확인해요',`<form data-wf-form="purchase" data-id="${id}"><h3>${esc(row.name)}</h3><div class="workflow-fields">${field('구매 날짜','day',today(),'date','required')}${field('구매 수량·단위','quantity',row.quantity,'text','maxlength="80"')}${numberField('실제 결제 금액 (원)','paid',row.estimate??'','required step="1"')}${field('표시 기한 (선택)','expiry','','date')}<label>넣을 곳<select name="zone">${Object.entries(zoneNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><label class="check-row"><input type="checkbox" name="expense" checked>식비로 기록</label><label class="check-row"><input type="checkbox" name="stock" checked>냉장고에 별도 묶음으로 넣기</label>${hint('확인하면 선택한 항목을 반영하고 이 장보기 항목을 목록에서 빼요. 기한을 모르면 빈칸으로 두세요.')}<button class="small-action primary" type="submit">확인하고 반영</button></form>`,'purchase');}
function budget(){const s=flow(),report=F.monthly(s,play(),viewMonth);open('이번 달 식비',`<label class="workflow-label">살펴볼 월<input type="month" id="budgetMonth" value="${viewMonth}"></label><div class="workflow-total"><span>실제 식비</span><b>${won(report.spending)}</b></div><p class="tray-note">예산 ${won(report.budget)}${report.budget!==null?' · 남은 예산 '+won(report.budget-report.spending):''}</p><div class="workflow-budget-track"><i style="width:${report.budget?Math.min(100,report.spending/report.budget*100):0}%"></i></div><form data-wf-form="budget"><h3>이달의 예산</h3><div class="workflow-fields">${numberField('월 예산 (원)','budget',report.budget??'','required step="1"')}</div><button class="small-action" type="submit">예산 저장</button></form><h3>실제 지출 기록</h3>${report.expenses.map(r=>`<div class="workflow-row"><div><strong>${esc(r.name)}</strong><small>${esc(r.day)} · ${{groceries:'장보기',eatingout:'외식',delivery:'배달'}[r.category]}</small></div><span class="amount">${won(r.amount)}</span>${button('수정','editExpense',r.id)}${button('취소','removeExpense',r.id)}</div>`).join('')||'<p class="workflow-empty">기록된 지출이 없어요.</p>'}<form data-wf-form="expense"><h3>지출 직접 추가</h3><div class="workflow-fields">${field('날짜','day',today(),'date','required')}${field('내용','name','','text','required maxlength="120"')}${numberField('실제 금액 (원)','amount','','required step="1"')}<label>분류<select name="category"><option value="groceries">장보기</option><option value="eatingout">외식</option><option value="delivery">배달</option></select></label></div><button class="small-action primary" type="submit">실제 지출 저장</button></form>${hint('식단의 예상 원가나 먹은 재료비를 실제 구매 지출에 다시 더하지 않아요. 지출 취소는 해당 금액만 취소하며 재고를 임의로 되돌리지 않아요.')}`,'budget');}
function supplements(){const rows=flow().supplements;open('내 영양제 기록',`${hint('제품 표시량과 내가 정한 일정의 기록이에요. 성분표를 확인하고 중복된 성분은 따로 살펴보세요.')}<label class="workflow-label">체크할 날짜<input type="date" id="supplementDay" value="${viewDay}"></label>${rows.map(r=>`<section class="workflow-card"><h3>${esc(r.name)}</h3><p class="tray-note">제품 표시량: ${esc(r.amount||'미입력')}<br>내 일정: ${esc(r.schedule||'미입력')}<br>남은 수량: ${esc(r.remaining||'미입력')}</p><label class="check-row"><input type="checkbox" data-supplement-check="${r.id}" ${r.days.includes(viewDay)?'checked':''}>오늘 복용함</label><details><summary>성분표 메모</summary><p class="tray-note">${esc(r.ingredients||'미입력')}</p></details>${footer(button('수정','editSupplement',r.id)+button('기록 삭제','removeSupplement',r.id))}</section>`).join('')||'<p class="workflow-empty">등록한 영양제가 없어요.</p>'}${button('중복 성분 이름 확인','supplementDuplicates')}<form data-wf-form="supplement"><h3>영양제 추가</h3><div class="workflow-fields">${field('제품 이름','name','','text','required maxlength="120"')}${field('제품 표시량','amount','','text','maxlength="500" placeholder="예: 제품에 적힌 1회 표시량"')}${field('남은 수량 (직접 입력)','remaining','','text','maxlength="80"')}${field('내 복용 일정','schedule','','text','maxlength="500" placeholder="내가 정한 시간·메모"')}<label>성분 이름 (쉼표 구분)<textarea name="ingredients" rows="2" maxlength="500"></textarea></label></div><button type="submit" class="small-action primary">내 일정에 추가</button></form>`,'supplements');}
function monthly(){const s=flow(),p=play(),r=F.monthly(s,p,viewMonth),[year,month]=viewMonth.split('-').map(Number),last=new Date(year,month,0).getDate(),offset=(new Date(year,month-1,1).getDay()+6)%7;open('한 달의 식탁',`<label class="workflow-label">살펴볼 월<input type="month" id="reviewMonth" value="${viewMonth}"></label><div class="workflow-month">${['월','화','수','목','금','토','일'].map(n=>`<strong>${n}</strong>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:last},(_,n)=>{const d=viewMonth+'-'+String(n+1).padStart(2,'0'),meals=r.meals.filter(m=>m.day===d),recipe=find(meals[0]?.recipeId);return `<div>${n+1}${recipe?dish(recipe):''}<small>${meals.length?meals.length+'끼 기록':'미기록'}</small></div>`;}).join('')}</div><p class="tray-note">식사 기록 ${r.days}/${last}일 · 미기록 ${last-r.days}일</p><div class="workflow-total"><span>실제 식비</span><b>${won(r.spending)}</b></div><p class="tray-note">월 예산 ${won(r.budget)}</p><h3>기록한 식사의 영양 비율</h3>${r.ratio?`<div class="workflow-grid">${Object.entries(r.ratio).map(([k,v])=>`<div class="workflow-card"><strong>${M.NUTRIENTS[k][0]}</strong><span>${fmt(v)}%</span></div>`).join('')}</div><p class="workflow-hint">탄수화물·단백질·지방을 모두 입력한 ${r.complete}끼의 에너지 비율이에요. 빠진 영양값은 0으로 가정하지 않아요.</p>`:'<p class="workflow-empty">탄수화물·단백질·지방을 함께 기록하면 비율을 볼 수 있어요.</p>'}<h3>그달의 요리</h3><p class="tray-note">${new Set(r.meals.map(m=>m.recipeId).filter(Boolean)).size}종의 요리를 기록했어요.</p>${footer(button('식비 보기','budget')+button('요리 도감','book')+button('기록 내보내기','settings'))}`,'monthly');}
function decor(){const t=flow().theme;open('나의 부엌 꾸미기',`<p class="tray-note">열린 냉장고의 정리함·라벨과 부엌의 분위기를 골라 보세요. 기존 재고와 기한은 바뀌지 않아요.</p><form data-wf-form="theme"><div class="workflow-fields"><label>배경 분위기<select name="background"><option value="linen" ${t.background==='linen'?'selected':''}>아이보리 햇살</option><option value="stone" ${t.background==='stone'?'selected':''}>차분한 스톤</option></select></label><label>재료 라벨<select name="labels"><option value="standard" ${t.labels==='standard'?'selected':''}>실버 테두리</option><option value="minimal" ${t.labels==='minimal'?'selected':''}>미니멀 라벨</option></select></label></div><label class="check-row"><input type="checkbox" name="organizer" ${t.organizer?'checked':''}>정리함 테두리 표시</label><button type="submit" class="small-action primary">부엌에 적용</button></form><h3>요리하며 모은 소품</h3>${footer(button('내가 고르는 목표·보상','rewards')+button('조리대 소품 자유 배치','counterDecor')+button('부엌으로 돌아가기','home'))}`,'decor');}
function targetsForm(returnTo='targets'){
 const state=play(),s=flow(),primary=['carb','protein','fat'],other=['kcal','fiber','water'];
 return `<form data-wf-form="targets" data-return="${returnTo}" class="target-form"><div class="target-intro"><h3>내가 정하는 하루 목표</h3><p>먹은 양 옆에 나의 목표를 함께 표시해요.</p></div><div class="workflow-fields target-primary">${primary.map(k=>{const [n,u]=M.NUTRIENTS[k];return numberField(n+' ('+u+')',k,state.targets[k]??'','min="0.01" placeholder="미설정"');}).join('')}</div><details class="target-extras"><summary>열량·수분·추가 성분 목표</summary><div class="workflow-fields">${other.map(k=>{const [n,u]=M.NUTRIENTS[k];return numberField(n+' ('+u+')',k,state.targets[k]??'','min="0.01" placeholder="미설정"');}).join('')}${Object.entries(EXTRA).map(([k,[n,u]])=>numberField(n+' ('+u+')',k,s.extraTargets?.[k]??'','min="0.01" placeholder="미설정"')).join('')}</div></details>${hint('직접 정한 목표예요. 공식 개인 권장량은 연결 전이며, 빈칸은 미설정으로 남아요.')}<div class="workflow-footer"><button type="submit" class="small-action primary">하루 목표 저장</button>${returnTo==='targets'?button('오늘의 영양','nutrition'):''}</div></form>`;
}
function targets(){open('나의 하루 목표',targetsForm('targets'),'targets');}
function settings(){
 const s=flow(),status={saved:'이 기기에 저장하고 있어요',temporary:'임시 세션 · 백업으로 보관해 주세요',blocked:'이전 원본 보존 · 새 저장 중단',conflict:'다른 화면의 기록 변경 · 새 저장 중단'}[J.status],needsRecovery=['blocked','conflict'].includes(J.status);
 open('목표와 설정',`${targetsForm('settings')}<form data-wf-form="preferences" class="preferences-form"><h3>식사 선호</h3>${field('피할 재료 (쉼표로 구분)','exclusions',s.exclusions,'text','maxlength="500" placeholder="예: 새우, 땅콩"')}<button type="submit" class="small-action">선호 저장</button></form><section class="storage-summary"><h3>기록 보관</h3><p class="workflow-note ${needsRecovery?'warning':''}">${status}</p><p class="workflow-hint">이 검토 화면의 기록만 다뤄요. 기존 앱 기록과 별도이며 기기 간 동기화는 연결 전이에요.</p></section><details class="backup-tools" ${needsRecovery?'open':''}><summary><strong>백업·복구</strong><span>내보내기 · 가져오기 · 이전 원본</span></summary>${footer(button('백업 파일 내보내기','downloadBackup'))}<label class="workflow-label">복사해서 보관할 백업<textarea id="journalExport" rows="4" readonly>${esc(JSON.stringify(J.getEnvelope(),null,2))}</textarea></label><form data-wf-form="import"><h3>백업 가져오기</h3><label class="workflow-label">백업 붙여넣기<textarea name="backup" rows="4" required></textarea></label><button type="submit" class="small-action">복구 전 미리보기</button></form>${J.recovery?`<details><summary>이전 원본·복구 자료 보관</summary><textarea rows="4" readonly>${esc(J.recovery)}</textarea></details>`:''}</details>${footer(button('사진으로 재료 등록','photos')+button('전체 기록 보기','hub'))}`,'settings');
}
function previewImport(raw){const data=JSON.parse(raw);if(!J.validEnvelope(data))throw new Error('올바른 백업 형식인지 확인해 주세요. 현재 기록은 변경하지 않았어요.');pendingImport=data;const current=J.getEnvelope();open('복구 전 내용을 확인해 주세요',`<div class="pending-import"><table class="workflow-table"><thead><tr><th>기록</th><th>현재</th><th>가져올 백업</th></tr></thead><tbody><tr><td>재료·소품</td><td>${current.world.items.length}</td><td>${data.world.items.length}</td></tr><tr><td>식사</td><td>${current.play.meals.length}</td><td>${data.play.meals.length}</td></tr><tr><td>식비</td><td>${current.workflow.expenses.length}</td><td>${data.workflow?.expenses.length||0}</td></tr></tbody></table>${hint('확인하면 이 시안의 현재 기록을 백업의 내용으로 교체해요. 교체 전 원본을 보관하며, 원래 앱의 기록은 바꾸지 않아요.')}<div class="workflow-footer">${button('돌아가기','settings')}${button('확인하고 불러오기','confirmImport','',true)}</div></div>`,'importPreview');}
function dispatch(name,arg=''){
 const map={hub,inventory,add,recipes,shopping,budget,supplements,monthly,decor,settings,targets,nutrition,plan,photos:()=>photoPage(false),fridgePhoto:()=>photoPage(true),manualAdd:()=>manualAdd(false),seasoningAdd:()=>manualAdd(true),wholeCandidates,book:()=>J.show('book'),rewards:()=>J.show('rewards')};
 if(map[name])return map[name]();
 if(name==='home'){K.closeTray();K.setCamera('fridge');return;}
 if(name==='backupTools'){settings();const tools=$('#trayContent .backup-tools');if(tools){tools.open=true;tools.scrollIntoView({block:'start'});}return;}
 if(name==='manualNoPhoto'){photoDraft={product:null,expiry:null,fridge:null};return manualAdd(false);}
 if(name==='item')return K.showItem(arg);
 if(name==='editMeal'){const m=play().meals.find(m=>m.id===arg);if(m)return logMeal(m.recipeId,m.id);return;}
 if(name==='recipe')return recipe(arg);
 if(name==='recipeFacts')return factsForm(arg);
 if(name==='logMeal')return logMeal(arg||null);
 if(name==='planRecipe')return plan(arg);
 if(name==='ingredientRecipes'){selectedIngredient=arg;return recipes();}
 if(name==='recipesReset'){selectedIngredient='';filters={budget:'',time:'',exclude:''};return recipes();}
 if(name==='planDay'){viewDay=arg;return plan();}
 if(name==='expirySort'||name==='inventoryReset'){search='';expiryFilter='';return inventory();}
 if(name==='expiryFilter'){search='';expiryFilter=arg;return inventory();}
 if(name==='purchase')return purchase(arg);
 if(name==='counterRecipe'){K.chooseRecipe(find(arg).name);return;}
 if(name==='counterDecor'){K.decorate();return;}
 if(name==='layerFront'||name==='layerBack'){J.transact(({world:w})=>{const i=w.items.find(x=>x.id===arg);if(i){const others=w.items.filter(x=>x.zone===i.zone&&x!==i).sort((a,b)=>a.z-b.z);if(name==='layerFront')others.push(i);else others.unshift(i);others.forEach((x,n)=>x.z=n+1);}});K.closeTray();return;}
 if(name==='deplete'||name==='waste'){const before=clone(world().items.find(x=>x.id===arg));J.transact(({world:w})=>{const i=w.items.find(x=>x.id===arg);i.depleted=true;i.manualRevision=(i.manualRevision||0)+1;lastStockUndo={before,after:clone(i)};});inventory();error(name==='waste'?'선택한 재료를 폐기 상태로 기록했어요. 실행 취소할 수 있어요.':'소진으로 표시했어요. 실행 취소할 수 있어요.');return;}
 if(name==='stockUndo'){if(!lastStockUndo)throw new Error('되돌릴 재료 변경이 없어요.');J.transact(({world:w})=>{const idx=w.items.findIndex(x=>x.id===lastStockUndo.after.id);if(idx<0||JSON.stringify(w.items[idx])!==JSON.stringify(lastStockUndo.after))throw new Error('그 뒤에 재료가 바뀌었어요. 현재 수량을 먼저 확인해 주세요.');w.items[idx]=clone(lastStockUndo.before);});lastStockUndo=null;inventory();return;}
 if(name==='candidateAdd'){const n=all('#candidateRows [data-candidate]').length;if(n>=20)throw new Error('한 번에 20개까지 입력할 수 있어요.');$('#candidateRows').insertAdjacentHTML('beforeend',candidateRow(n));return;}
 if(name==='missingToShopping'){const r=find(arg),x=matches(r);J.transact(({flow:s})=>{for(const n of x.missing)if(!s.shopping.some(i=>i.name===n))s.shopping.push({id:key('shop'),name:n,quantity:r.amounts[n]||'',estimate:null,checked:false});});return shopping();}
 if(name==='planShopping'){for(const p of flow().plans.filter(p=>p.day===arg))dispatch('missingToShopping',p.recipeId);return shopping();}
 if(name==='removePlan'){J.transact(({flow:s})=>{s.plans=s.plans.filter(p=>p.id!==arg);});return plan();}
 if(name==='removeShopping'){J.transact(({flow:s})=>{s.shopping=s.shopping.filter(r=>r.id!==arg);});return shopping();}
 if(name==='editExpense'){const r=flow().expenses.find(x=>x.id===arg);if(!r)return;open('지출 기록 수정',`<form data-wf-form="editExpense" data-id="${r.id}"><div class="workflow-fields">${field('날짜','day',r.day,'date','required')}${field('내용','name',r.name,'text','required maxlength="120"')}${numberField('실제 금액 (원)','amount',r.amount,'required step="1"')}<label>분류<select name="category">${[['groceries','장보기'],['eatingout','외식'],['delivery','배달']].map(([k,v])=>`<option value="${k}" ${r.category===k?'selected':''}>${v}</option>`).join('')}</select></label></div><button type="submit" class="small-action primary">수정 저장</button></form>`,'editExpense');return;}
 if(name==='removeExpense'){J.transact(({flow:s})=>{s.expenses=s.expenses.filter(r=>r.id!==arg);});return budget();}
 if(name==='editSupplement'){const r=flow().supplements.find(x=>x.id===arg);if(!r)return;open('영양제 기록 수정',`<form data-wf-form="editSupplement" data-id="${r.id}"><div class="workflow-fields">${field('제품 이름','name',r.name,'text','required maxlength="120"')}${field('제품 표시량','amount',r.amount,'text','maxlength="500"')}${field('내 일정','schedule',r.schedule,'text','maxlength="500"')}${field('남은 수량','remaining',r.remaining||'','text','maxlength="80"')}<label>성분 이름<textarea name="ingredients" rows="3" maxlength="500">${esc(r.ingredients)}</textarea></label></div><button class="small-action primary" type="submit">수정 저장</button></form>`,'editSupplement');return;}
 if(name==='removeSupplement'){J.transact(({flow:s})=>{s.supplements=s.supplements.filter(r=>r.id!==arg);});return supplements();}
 if(name==='supplementDuplicates'){const counts=new Map();for(const r of flow().supplements){for(const n of new Set(r.ingredients.split(/[,\n]/).map(x=>x.trim()).filter(Boolean))){const k=clean(n);counts.set(k,{name:n,count:(counts.get(k)?.count||0)+1});}}const duplicates=[...counts.values()].filter(x=>x.count>1);error(duplicates.length?'중복 입력된 성분 이름: '+duplicates.map(x=>x.name+' ('+x.count+'개 제품)').join(', ')+'. 표시량과 실제 섭취량은 별도로 확인해 주세요.':'입력된 성분 이름 중 중복이 없어요. 미입력 성분이나 실제 함량은 확인한 결과가 아니에요.');return;}
 if(name==='confirmCancelMeal'){J.transact(({world:w,play:p,flow:s})=>{const record=p.state().meals.find(r=>r.id===arg);if(!record)throw new Error('식사 기록을 다시 확인해 주세요.');const t=s.transactions.find(x=>x.mealId===arg&&x.active);if(t){F.reverseDeductions(w,t.deductions);t.active=false;}s.lastCanceled={record:clone(record)};p.remove(arg);});nutrition();error('식사와 연결된 영양·재고를 함께 되돌렸어요. 취소 복구로 다시 불러올 수 있어요.');return;}
 if(name==='confirmImport'){if(!pendingImport)throw new Error('먼저 가져올 백업을 확인해 주세요.');J.replaceEnvelope(pendingImport);pendingImport=null;settings();error('백업을 불러왔어요. 저장 상태와 이전 원본도 확인해 주세요.');return;}
 if(name==='downloadBackup'){const blob=new Blob([JSON.stringify(J.getEnvelope(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='한끼의부엌-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
}
function nullable(f,name){const raw=f.get(name);return raw===null||raw===''?null:Number(raw);}
function submit(form){const f=new FormData(form),type=form.dataset.wfForm;
 if(type==='search'){search=String(f.get('search'));return inventory();}
 if(type==='recipeFilters'){selectedIngredient=String(f.get('ingredient'));filters={budget:String(f.get('budget')),time:String(f.get('time')),exclude:String(f.get('exclude'))};return recipes();}
 if(type==='item'){const id=form.dataset.id;J.transact(({world:w})=>{const i=w.items.find(x=>x.id===id);if(!i)throw new Error('재료를 확인해 주세요.');if(i.quantity!==String(f.get('quantity')).trim())i.manualRevision=(i.manualRevision||0)+1;i.name=String(f.get('name')).trim();i.quantity=String(f.get('quantity')).trim();i.expiry=String(f.get('expiry'));i.opened=String(f.get('opened'));i.expiryType=String(f.get('expiryType'));if(attachment){i.photo=attachment;i.photoAsIcon=true;}if(i.zone!==f.get('zone')){i.zone=String(f.get('zone'));i.x=.5;i.y=.63;i.z=++w.layer;}i.depleted=false;const z=i.zone.startsWith('door')?i.zone.slice(4,5).toLowerCase()+i.zone.slice(5):i.zone;if(Object.hasOwn(w.doors,z))w.doors[z]=true;});K.setCamera(['seasoning','counter'].includes(String(f.get('zone')))?String(f.get('zone')):'fridge');K.closeTray();K.announce('수량·기한·위치를 저장했어요.');return;}
 if(type==='add'){J.transact(({world:w})=>{const merge=String(f.get('mergeId')||'');if(merge){const target=w.items.find(i=>i.id===merge),have=target&&F.parseQuantity(target.quantity),extra=F.parseQuantity(String(f.get('quantity')));if(!target||clean(target.name)!==clean(String(f.get('name')))||!String(f.get('expiry'))||target.expiry!==String(f.get('expiry'))||(target.opened||'')!==String(f.get('opened'))||!have||!extra||have.baseUnit!==extra.baseUnit)throw new Error('같은 기한·개봉일·단위인 묶음만 합칠 수 있어요. 별도 묶음으로 추가해 주세요.');target.quantity=F.quantity(have.baseAmount+extra.baseAmount,have);target.manualRevision=(target.manualRevision||0)+1;target.depleted=false;}else F.addItem(w,{name:String(f.get('name')),quantity:String(f.get('quantity')),expiry:String(f.get('expiry')),opened:String(f.get('opened')),kind:String(f.get('kind')),zone:String(f.get('zone')),photo:photoDraft.product,photoAsIcon:f.get('picture')==='photo',expiryPhoto:photoDraft.expiry});});photoDraft={product:null,expiry:null,fridge:null};K.setCamera('fridge');K.closeTray();K.announce('확인한 재료를 별도 묶음으로 추가했어요.');return;}
 if(type==='candidates'){const count=all('#candidateRows [data-candidate]').length;J.transact(({world:w})=>{for(let n=0;n<count;n++)if(f.has('include'+n))F.addItem(w,{name:String(f.get('name'+n)),quantity:String(f.get('quantity'+n)),expiry:String(f.get('expiry'+n)),zone:String(f.get('zone'+n))});});K.setCamera('fridge');K.closeTray();K.announce('직접 확인한 후보만 추가했어요.');return;}
 if(type==='facts'){J.transact(({flow:s})=>{s.recipeFacts[form.dataset.id]={...Object.fromEntries(Object.keys(M.NUTRIENTS).map(k=>[k,nullable(f,k)])),...Object.fromEntries(Object.keys(EXTRA).map(k=>[k,nullable(f,k)])),cost:nullable(f,'cost'),source:String(f.get('source'))};});return recipe(form.dataset.id);}
 if(type==='recipeNotes'){J.transact(({flow:s})=>{s.recipeNotes[form.dataset.id]={note:String(f.get('note')),variation:String(f.get('variation'))};});error('내 팁과 대체 재료를 저장했어요.');return;}
 if(type==='meal'){const recipeId=form.dataset.id||null,recipeRow=find(recipeId),portions=Number(f.get('portions'));if(!Number.isFinite(portions)||portions<=0||portions>100)throw new Error('먹은 비율을 확인해 주세요.');J.transact(({world:w,play:p,flow:s})=>{const editing=form.dataset.edit;if(editing){const old=s.transactions.find(t=>t.mealId===editing&&t.active);if(old){F.reverseDeductions(w,old.deductions);old.active=false;}if(!p.remove(editing))throw new Error('수정할 식사를 확인해 주세요.');}const requests=[];all('#workflowMealForm .usage-row').forEach((row,n)=>{if(f.has('use'+n)){const item=w.items.find(x=>x.id===f.get('item'+n));if(item?.expiry&&item.expiry<String(f.get('day')))throw new Error(item.name+'의 기록된 기한이 지났어요. 사용량을 다시 확인해 주세요.');requests.push({itemId:String(f.get('item'+n)),quantity:String(f.get('qty'+n))});}});const deductions=F.applyDeductions(w,requests);const result=p.record({day:String(f.get('day')),name:String(f.get('name')),portion:String(f.get('portion')||portions+'회분'),recipeId,nutrients:Object.fromEntries(Object.keys(M.NUTRIENTS).map(k=>[k,nullable(f,k)]))});s.extraNutrients[result.record.id]=Object.fromEntries(Object.keys(EXTRA).map(k=>[k,nullable(f,k)]));s.transactions.push({id:key('txn'),mealId:result.record.id,deductions,active:true});s.lastCanceled=null;});viewDay=String(f.get('day'));nutrition();error('식사·입력한 영양·확인한 재료 차감을 함께 기록했어요.');return;}
 if(type==='plan'){const id=String(f.get('recipeId'));if(!find(id))throw new Error('요리를 확인해 주세요.');J.transact(({flow:s})=>{s.plans.push({id:key('plan'),day:String(f.get('day')),slot:String(f.get('slot')),recipeId:id,portions:Number(f.get('portions'))});});viewDay=String(f.get('day'));return plan();}
 if(type==='shopping'){J.transact(({flow:s})=>{s.shopping.push({id:key('shop'),name:String(f.get('name')).trim(),quantity:String(f.get('quantity')).trim(),estimate:nullable(f,'estimate'),checked:false});});return shopping();}
 if(type==='purchase'){J.transact(({world:w,flow:s})=>{const row=s.shopping.find(x=>x.id===form.dataset.id);if(!row)throw new Error('이미 반영했거나 삭제한 항목이에요.');const paid=Number(f.get('paid'));if(!Number.isInteger(paid)||paid<0||paid>1e9)throw new Error('실제 결제 금액을 확인해 주세요.');if(f.has('expense'))s.expenses.push({id:key('expense'),day:String(f.get('day')),name:row.name,amount:paid,category:'groceries'});if(f.has('stock'))F.addItem(w,{name:row.name,quantity:String(f.get('quantity')),expiry:String(f.get('expiry')),zone:String(f.get('zone'))});s.shopping=s.shopping.filter(x=>x.id!==row.id);});shopping();error('선택한 지출 기록과 재고 입고를 반영했어요.');return;}
 if(type==='budget'){J.transact(({flow:s})=>{s.budgets[viewMonth]=Number(f.get('budget'));});return budget();}
 if(type==='expense'){J.transact(({flow:s})=>{s.expenses.push({id:key('expense'),day:String(f.get('day')),name:String(f.get('name')).trim(),amount:Number(f.get('amount')),category:String(f.get('category'))});});viewMonth=String(f.get('day')).slice(0,7);return budget();}
 if(type==='editExpense'){J.transact(({flow:s})=>{const r=s.expenses.find(x=>x.id===form.dataset.id);if(!r)throw new Error('지출을 확인해 주세요.');Object.assign(r,{day:String(f.get('day')),name:String(f.get('name')).trim(),amount:Number(f.get('amount')),category:String(f.get('category'))});});viewMonth=String(f.get('day')).slice(0,7);return budget();}
 if(type==='supplement'){J.transact(({flow:s})=>{s.supplements.push({id:key('supplement'),name:String(f.get('name')).trim(),amount:String(f.get('amount')),schedule:String(f.get('schedule')),ingredients:String(f.get('ingredients')),remaining:String(f.get('remaining')||''),days:[]});});return supplements();}
 if(type==='editSupplement'){J.transact(({flow:s})=>{const r=s.supplements.find(x=>x.id===form.dataset.id);if(!r)throw new Error('영양제를 확인해 주세요.');Object.assign(r,{name:String(f.get('name')).trim(),amount:String(f.get('amount')),schedule:String(f.get('schedule')),ingredients:String(f.get('ingredients')),remaining:String(f.get('remaining'))});});return supplements();}
 if(type==='theme'){J.transact(({flow:s})=>{s.theme={background:String(f.get('background')),labels:String(f.get('labels')),organizer:f.has('organizer')};});K.closeTray();K.setCamera('fridge');return;}
 if(type==='targets'){J.transact(({play:p,flow:s})=>{s.extraTargets=Object.fromEntries(Object.keys(EXTRA).map(k=>[k,nullable(f,k)]));p.setTargets(Object.fromEntries(Object.keys(M.NUTRIENTS).map(k=>[k,nullable(f,k)])));});if(form.dataset.return==='settings')settings();else targets();error('직접 정한 목표를 저장했어요.');return;}
 if(type==='preferences'){J.transact(({flow:s})=>{s.exclusions=String(f.get('exclusions')).trim();});error('피할 재료를 저장했어요.');return;}
 if(type==='import')return previewImport(String(f.get('backup')));
}
async function photoData(file){if(!file||!file.type.startsWith('image/'))throw new Error('이미지 파일을 선택해 주세요.');if(file.size>12*1024*1024)throw new Error('12MB 이하의 이미지를 선택해 주세요.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(new Error('사진을 열 수 없어요. JPG·PNG로 다시 선택해 주세요.'));img.src=url;});const ratio=Math.min(1,420/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.78);if(data.length>=250000)throw new Error('사진 용량이 커요. 더 작은 사진을 선택해 주세요.');return data;}finally{URL.revokeObjectURL(url);}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.workflow)dispatch(b.dataset.workflow);if(b.dataset.wf)dispatch(b.dataset.wf,b.dataset.arg||'');}catch(err){error(err.message);}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.wfForm)return;e.preventDefault();try{submit(form);}catch(err){error(err instanceof SyntaxError?'백업 JSON을 읽을 수 없어요. 현재 기록은 유지돼요.':err.message);}});
document.addEventListener('change',async e=>{const x=e.target;try{
 if(x.dataset.photo){const requestedRoute=route,requestedItem=activeItem;const value=await photoData(x.files?.[0]);if(route!==requestedRoute||activeItem!==requestedItem)return;if(x.dataset.photo==='item'){attachment=value;$('#itemPhotoPreview').innerHTML=`<img class="workflow-photo" src="${value}" alt="선택한 제품 사진">`;}else{photoDraft[x.dataset.photo]=value;photoPage(x.dataset.photo==='fridge');}return;}
 if(x.dataset.shoppingCheck){J.transact(({flow:s})=>{const r=s.shopping.find(x=>x.id===e.target.dataset.shoppingCheck);if(r)r.checked=e.target.checked;});return;}
 if(x.dataset.supplementCheck){J.transact(({flow:s})=>{const r=s.supplements.find(r=>r.id===x.dataset.supplementCheck);if(!r)return;if(x.checked&&!r.days.includes(viewDay))r.days.push(viewDay);if(!x.checked)r.days=r.days.filter(d=>d!==viewDay);});return;}
 if(x.id==='planDay'&&F.day(x.value)){viewDay=x.value;plan();}
 if(x.id==='supplementDay'&&F.day(x.value)){viewDay=x.value;supplements();}
 if(x.id==='budgetMonth'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(x.value)){viewMonth=x.value;budget();}if(x.id==='reviewMonth'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(x.value)){viewMonth=x.value;monthly();}
 if(x.name==='portions'&&x.closest('#workflowMealForm')){const r=find(x.form.dataset.id),facts=r&&flow().recipeFacts[r.id],ratio=Number(x.value);if(ratio>0&&ratio<=100){if(facts)for(const k of [...Object.keys(M.NUTRIENTS),...Object.keys(EXTRA)])if(facts[k]!==null&&facts[k]!==undefined)x.form.elements[k].value=F.round(facts[k]*ratio);if(r)all('#workflowMealForm .usage-row').forEach((row,n)=>{const amount=F.parseQuantity(Object.values(r.amounts)[n]);if(amount&&x.form.elements['use'+n].checked)x.form.elements['qty'+n].value=String(F.round(amount.amount*ratio))+amount.unit;});}}
 }catch(err){error(err.message);}});
document.addEventListener('input',e=>{if(e.target.name==='name'&&e.target.closest('#addIngredientForm')){const matches=world().items.filter(i=>['food','seasoning'].includes(i.kind)&&clean(i.name)===clean(e.target.value));$('#duplicateHint').innerHTML=matches.length?hint('같은 이름의 묶음이 '+matches.length+'개 있어요. 기본은 별도 등록이에요. 합치기는 기한·개봉일·단위가 같을 때만 가능해요.')+'<label class="workflow-label">등록 방식<select name="mergeId"><option value="">별도 묶음으로 추가</option>'+matches.map(i=>'<option value="'+esc(i.id)+'">기존 '+esc(i.quantity)+' · '+esc(i.expiry||'기한 미입력')+'에 합치기</option>').join('')+'</select></label>':'';}});
window.KitchenWorkflows=Object.freeze({add,recipes,item,recipe,decor,update,logMeal,enhanceJournal,cancelMeal,undoMeal,previewImport,show:dispatch,selectedAction(){const s=K.getSnapshot(),i=s.items.find(i=>i.id===s.selected);if(i){selectedIngredient=i.name;recipes();}else inventory();}});
window.addEventListener('mini-kitchen:layout',()=>{if(!$('#dailyBalance').children.length)update();});
update();
})();
